questions.stem:
A parking meter bills by length of stay, and the tiers were entered in the wrong order:
int hours = 4;
double fee;
if (hours > 2) {
    fee = 8.0;
} else if (hours > 4) {
    fee = 12.0;
} else {
    fee = 5.0;
}
System.out.println(fee);
What prints?

A registrar wants A at 90 and up, B at 70 and up, C at 60 and up, F below that, but the bands were typed in ascending order. Given a score of 85, what letter is awarded?
int score = 85;
char letter;
if (score >= 60) {
    letter = 'C';
} else if (score >= 70) {
    letter = 'B';
} else if (score >= 90) {
    letter = 'A';
} else {
    letter = 'F';
}
System.out.println(letter);

A bulk-order program promises 15 percent off at more than ten items and 5 percent off at more than zero. How much discount is recorded for a ten-item order?
int items = 10;
int discount;
if (items > 10) {
    discount = 15;
} else if (items > 0) {
    discount = 5;
} else {
    discount = 0;
}
System.out.println(discount);

Shipping is free at 50.00 or more and costs 6.95 below that. Fill the gap so 50.00 ships free and 49.99 does not.
double total = 75.0;
double shipping = 6.95;
if (GAP) {
    shipping = 0.0;
}
System.out.println(shipping);

A discount service holds an optional coupon code from a request. What happens here?
String coupon = null;
int saved = 0;
if (coupon != null && coupon.length() > 3) {
    saved = coupon.length();
}
System.out.println(saved);

A retry counter is tested before it is allowed to advance. What value survives?
int count = 0;
if (count > 0 && count++ < 5) {
    count = 99;
}
System.out.println(count);

A health check only probes the sensor when the device is not already known to be offline. How many probes are recorded?
int probes = 0;
boolean offline = true;
if (offline || probes++ > 0) {
}
System.out.println(probes);

An access rule is written without parentheses. What is stored in r?
boolean a = true;
boolean b = false;
boolean c = true;
boolean r = a || b && !c;
System.out.println(r);

A cashier flag is compared against a literal in a single expression. What prints?
boolean member = true;
boolean discount = !member == true;
System.out.println(discount);

A shipping calculator dispatches on a two-letter country code read from a form, and the browser lowercased the submitted value. What prints?
String region = "us";
String label;
switch (region) {
    case "US": label = "domestic"; break;
    case "CA": label = "canada"; break;
    default: label = "other";
}
System.out.println(label);

A job runner builds an action name for known states, and the compiler rejects the code. Why?
String state = "paused";
String action;
switch (state) {
    case "running": action = "notify"; break;
    case "closed": action = "archive"; break;
}
System.out.println(action);

A star-rating band is assigned by a switch whose cases were written without breaks. What prints?
int stars = 3;
String band;
switch (stars) {
    case 5: band = "excellent";
    case 4: band = "good";
    case 3: band = "fair";
    case 2: band = "weak";
        break;
    default: band = "none";
}
System.out.println(band);

A parcel tracker switches on its Status type, but one case label was written in the wrong form. What happens?
enum Status { NEW, SHIPPED, CLOSED }
Status s = Status.SHIPPED;
String note;
switch (s) {
    case NEW: note = "received"; break;
    case "SHIPPED": note = "in transit"; break;
    default: note = "other";
}
System.out.println(note);

A discount schedule recognises only two shipping codes, and the fee already holds a sensible default. What prints?
int code = 7;
int fee = 3;
switch (code) {
    case 1: fee = 1; break;
    case 2: fee = 2; break;
}
System.out.println(fee);

A shop badge is built with the conditional operator. What prints?
int stock = 0;
String label = stock > 0 ? "in stock" : "out of stock";
System.out.println(label);

A score is mapped to a tier with a single conditional expression. What prints?
int score = 5;
String tier = score > 10 ? "pro" : score > 3 ? "basic" : "free";
System.out.println(tier);

A ratio is stored in a double, but the division inside the conditional operator is on two ints. What prints?
int a = 9;
int b = 2;
double ratio = a > b ? a / b : a % b;
System.out.println(ratio);

A pass rule tests two thresholds and the braces were left off. What prints?
int score = 55;
String band;
if (score >= 60)
    if (score >= 90) band = "A";
    else band = "F";
else band = "review";
System.out.println(band);

An inventory tag is set by a branch whose braces were dropped, so one line always runs. What prints?
int n = 7;
String tag;
if (n > 0)
    if (n > 10) tag = "big";
    tag = "positive";
System.out.println(tag);

A form accepts only the letters A through F as a grade. What is printed for the value K?
char grade = 'K';
boolean valid = grade >= 'A' && grade <= 'F';
System.out.println(valid);

A transit fare rule covers riders aged 18 up to but not including 65. Fill the gap.
int age = 42;
String band;
if (GAP) {
    band = "adult";
} else {
    band = "other";
}
System.out.println(band);

A card fee is set by an outer branch and then refined by an inner one. What prints?
int balance = 40;
int fee = 9;
if (balance > 0) {
    fee = 5;
    if (balance < 100) {
        fee = 0;
    }
}
System.out.println(fee);

A stock check clamps a negative reading and the chain has a separate case for zero. What prints?
int stock = -2;
String note;
if (stock < 0) {
    stock = 0;
    note = "clamped";
} else if (stock == 0) {
    note = "empty";
} else {
    note = "ok";
}
System.out.println(note);

A total is doubled after a conditional add, but the add has no braces. What prints?
int n = 5;
int total = 0;
if (n > 0)
    total = total + n;
    total = total * 2;
System.out.println(total);

A tax total is compared with a hardcoded expected rate. What prints?
double rate = 0.1 + 0.2;
if (rate == 0.3) {
    System.out.println("match");
} else {
    System.out.println("off");
}

A pass rule gives A, B and C the same outcome by stacking labels with no statements between them. What prints?
char grade = 'B';
String result;
switch (grade) {
    case 'A':
    case 'B':
    case 'C':
        result = "pass";
        break;
    case 'D':
    case 'F':
        result = "fail";
        break;
    default:
        result = "invalid";
}
System.out.println(result);

A unit-price calculator guards its division with a conditional expression and no parentheses. What happens?
int units = 0;
int price = 100;
int cost = units == 0 ? 0 : price / units;
System.out.println(cost);

A credit is spent only when one is available, so the decrement sits behind a guard in the same condition. What prints?
int credits = 3;
boolean ok = credits > 0 && (credits -= 1) >= 0;
System.out.println(credits);

An ATM caps withdrawals at the daily limit by rewriting the request when it is too large. What prints?
int request = 500;
int limit = 300;
if (request > limit) {
    request = limit;
}
System.out.println(request);

A settings row can be null when no override was saved, and the code switches on it directly. What happens?
String status = null;
String label;
switch (status) {
    case "on": label = "active"; break;
    case "off": label = "inactive"; break;
    default: label = "unknown";
}
System.out.println(label);
